"""Unit tests for Rust Cargo.lock parser."""

import pytest

from vulnify.parsers.cargo import CargoLockfileParser, parse_cargo_lock
from vulnify.parsers.models import DependencyParseError, FidelityLevel

SAMPLE_CARGO_LOCK = """
# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
version = 3

[[package]]
name = "payment-gateway"
version = "0.1.0"
dependencies = [
    "serde",
    "tokio 1.35.1 (registry+https://github.com/rust-lang/crates.io-index)",
]

[[package]]
name = "serde"
version = "1.0.197"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "3fb1c873e1b9b056a4dc4c0c198b24c3ffa059243875552b2bd0933b1aee4ce2"
dependencies = [
    "serde_derive",
]

[[package]]
name = "serde_derive"
version = "1.0.197"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "7eb0b34b42edc17f6b7cac84a52a1c5f0e1bb2227e997ca9011ea3dd34e8610b"

[[package]]
name = "tokio"
version = "1.35.1"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "c40388acf780d3ac97ca3c6368419b45325083c27352164dd8760c2366b4372f"
"""


def test_parse_valid_cargo_lock() -> None:
    graph = parse_cargo_lock(SAMPLE_CARGO_LOCK)
    # 3 external dependencies: serde, serde_derive, tokio (payment-gateway is root crate)
    assert len(graph.packages) == 3
    pkg_ids = {p.id for p in graph.packages}
    assert "cargo:serde@1.0.197" in pkg_ids
    assert "cargo:serde_derive@1.0.197" in pkg_ids
    assert "cargo:tokio@1.35.1" in pkg_ids

    # Ecosystem should be crates.io
    for p in graph.packages:
        assert p.ecosystem == "crates.io"
        assert p.purl.startswith("pkg:cargo/")

    # Direct dependencies from payment-gateway workspace crate
    assert "cargo:serde@1.0.197" in graph.direct_dependency_ids
    assert "cargo:tokio@1.35.1" in graph.direct_dependency_ids
    assert "cargo:serde_derive@1.0.197" not in graph.direct_dependency_ids

    # Transitive dependency edges: serde -> serde_derive
    edge_pairs = {(e.source_id, e.target_id) for e in graph.edges}
    assert ("cargo:serde@1.0.197", "cargo:serde_derive@1.0.197") in edge_pairs

    # Checksum verification
    serde_pkg = next(p for p in graph.packages if p.name == "serde")
    assert serde_pkg.checksum == "3fb1c873e1b9b056a4dc4c0c198b24c3ffa059243875552b2bd0933b1aee4ce2"

    assert graph.fidelity == FidelityLevel.EXACT_LOCKFILE.value


def test_cargo_empty_and_malformed() -> None:
    with pytest.raises(DependencyParseError):
        parse_cargo_lock("")

    with pytest.raises(DependencyParseError):
        parse_cargo_lock("not a valid toml [[[[]")


def test_cargo_parser_class_interface() -> None:
    parser = CargoLockfileParser()
    assert parser.ecosystem == "Cargo"
    assert "Cargo.lock" in parser.supported_filenames

    g = parser.parse(SAMPLE_CARGO_LOCK, "Cargo.lock")
    assert g.parser_id == "cargo_lock"
